import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { tmpdir } from "node:os";
import { access, mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";

//#region src/subpath/testing/fixtures/index.ts
var TemporaryProjectFixture = class {
	path;
	cleaned = false;
	constructor(path) {
		this.path = path;
	}
	async cleanup() {
		if (this.cleaned) return;
		this.cleaned = true;
		await rm(this.path, {
			force: true,
			recursive: true
		});
	}
	async exists(path) {
		try {
			await access(this.resolve(path));
			return true;
		} catch (error) {
			if (isMissingPathError(error)) return false;
			throw error;
		}
	}
	read(path) {
		return readFile(this.resolve(path), "utf8");
	}
	resolve(...segments) {
		const candidate = resolve(this.path, ...segments);
		const offset = relative(this.path, candidate);
		if (!offset.startsWith("..") && !isAbsolute(offset)) return candidate;
		throw new Error(`Project fixture path escapes its root: ${segments.join("/")}`);
	}
	async write(path, content) {
		const target = this.resolve(path);
		await mkdir(dirname(target), { recursive: true });
		await writeFile(target, content);
	}
};
const createProjectFixture = async (options = {}) => {
	const prefix = options.prefix ?? "func-project-";
	assertPrefix(prefix);
	const fixture = new TemporaryProjectFixture(await mkdtemp(join(tmpdir(), prefix)));
	try {
		for (const [path, content] of Object.entries(options.files ?? {})) await fixture.write(path, content);
		return fixture;
	} catch (error) {
		await fixture.cleanup();
		throw error;
	}
};
const withProjectFixture = async (options, callback) => {
	const fixture = await createProjectFixture(options);
	try {
		return await callback(fixture);
	} finally {
		await fixture.cleanup();
	}
};
const assertPrefix = (prefix) => {
	if (prefix.length && !prefix.includes("/") && !prefix.includes("\\")) return;
	throw new TypeError("Project fixture prefix must be a non-empty path segment.");
};
const isMissingPathError = (error) => error instanceof Error && "code" in error && error.code === "ENOENT";

//#endregion
export { createProjectFixture, withProjectFixture };